 receiveInventoryStock(){if(!this.selectedInventoryItem||this.inventorySaving())return;const quantity=Number(this.inventoryQty),unitCost=Number(this.inventoryCost);if(!Number.isFinite(quantity)||quantity<=0||!Number.isFinite(unitCost)||unitCost<0){this.inventoryActionError='Enter a positive quantity and valid unit cost.';return;}this.inventorySaving.set(true);this.inventoryActionError='';this.http.post(this.api+'/stock/receive',{itemId:this.selectedInventoryItem._id,quantity,unitCost},{headers:this.headers()}).subscribe({next:()=>this.inventorySaved(),error:e=>{this.inventorySaving.set(false);this.inventoryActionError=e.error?.error||'Stock-in failed.';}});}
