 salesTrend=signal<{date:string;revenue:number;entries:number;unitsSold:number}[]>([]);
 salesTrendLoading=signal(false);salesTrendError=signal('');
 get salesTrendTotal(){return this.salesTrend().reduce((sum,p)=>sum+p.revenue,0);}
 get salesTrendUnitsSold(){return this.salesTrend().reduce((sum,p)=>sum+(p.unitsSold||0),0);}
 get maxSalesUnits(){return Math.max(1,...this.salesTrend().map(p=>p.unitsSold||0));}
